#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: read-only cloud access to the TodoApp data for the Pi (issue #35).
# Run from the repo root on your laptop. Nothing here is committed: the values
# land in src/taskFetcher/.env (gitignored) here and on the Pi.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

ENV_FILE="src/taskFetcher/.env"
KEY_DIR_REMOTE=".config/tododisplay"   # relative to the Pi user's home
KEY_NAME="todoapp-reader.json"
SSH_OPTS=()

# pi_env KEY VALUE upserts KEY='VALUE' into the Pi's .env, like write_env does locally.
pi_env() {
  local key="$1" value="$2"
  ssh "${SSH_OPTS[@]}" "$PI_HOST" "bash -s -- $(printf '%q %q %q' "$PI_REPO" "$key" "$value")" <<'REMOTE'
set -e
f="$HOME/$1/src/taskFetcher/.env"; k="$2"; v="$3"
[ -e "$f" ] || (umask 077 && : > "$f")
tmp=$(mktemp); grep -vE "^${k}=" "$f" > "$tmp" || true
printf "%s='%s'\n" "$k" "${v//\'/\'\\\'\'}" >> "$tmp"
cat "$tmp" > "$f"; rm -f "$tmp"
REMOTE
  printf '  %s✓ wrote%s %s → %s:~/%s/src/taskFetcher/.env\n' "$GREEN" "$RESET" "$key" "$PI_HOST" "$PI_REPO"
}

# Override the library's open_url: some xdg-open setups block until the browser
# exits, which would hang the wizard. Launch detached and carry on.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  if command -v xdg-open >/dev/null 2>&1; then
    (setsid xdg-open "$url" >/dev/null 2>&1 </dev/null &)
  else
    warn "no browser launcher found, so visit it manually: $url"
  fi
}

banner "TodoApp: read-only cloud access for the Pi"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Find your project id and user id"
say "The Pi reads your TodoApp data from Firestore. We need two identifiers."
say "They stay in .env files only, never in git or GitHub issues."
open_url "https://console.firebase.google.com/"
step "Open your TodoApp project → gear icon → Project settings."
step "On the General tab, copy the Project ID."
ask TODOAPP_PROJECT_ID "Paste the project id:"
step "Now go to Build → Authentication → Users and copy your User UID."
note "Your data lives at spaces/<UID>, so this is also the space id."
ask TODOAPP_SPACE_ID "Paste the user UID:"
write_env TODOAPP_PROJECT_ID "$TODOAPP_PROJECT_ID"
write_env TODOAPP_SPACE_ID "$TODOAPP_SPACE_ID"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create a read-only service account"
say "The security rules let members write, so the Pi gets its own account that can only read."
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=${TODOAPP_PROJECT_ID}"
step "Service account name: todo-display-reader, then 'Create and continue'."
step "Under 'Grant this service account access', pick the role 'Cloud Datastore Viewer'."
note "That is roles/datastore.viewer: read-only on Firestore, nothing else."
step "Click 'Continue', then 'Done'. Leave the third box empty."
pause "Service account created?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create and download its key"
KEY_LOCAL="$HOME/$KEY_DIR_REMOTE/$KEY_NAME"
# key_ok FILE succeeds if FILE is the todo-display-reader key for this project.
key_ok() {
  python3 -I - "$1" "$TODOAPP_PROJECT_ID" 2>/dev/null <<'PY'
import json, sys
k = json.load(open(sys.argv[1]))
assert k["type"] == "service_account", "not a service account key"
assert k["project_id"] == sys.argv[2], "key belongs to a different project"
assert k["client_email"].startswith("todo-display-reader@"), "wrong service account"
PY
}
if key_ok "$KEY_LOCAL"; then
  say "✓ already have the key at $KEY_LOCAL, so skipping the download."
  write_env TODOAPP_KEY_FILE "$KEY_LOCAL"
  pause "Press Enter to continue"
else
  open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=${TODOAPP_PROJECT_ID}"
  step "Click todo-display-reader → Keys tab → Add key → Create new key → JSON → Create."
  step "A .json file downloads. Note where it went."
  note "If key creation is blocked, an organisation policy (iam.disableServiceAccountKeyCreation) is on."
  while true; do
    ask KEY_DOWNLOAD "Path to the downloaded file (drag it in, or ~/Downloads/...):"
    KEY_DOWNLOAD="${KEY_DOWNLOAD/#\~/$HOME}"
    KEY_DOWNLOAD="${KEY_DOWNLOAD//\\ / }"; KEY_DOWNLOAD="${KEY_DOWNLOAD//\'/}"
    key_ok "$KEY_DOWNLOAD" && break
    warn "that file isn't the todo-display-reader key for this project; try again"
  done
  mkdir -p "$(dirname "$KEY_LOCAL")" && chmod 700 "$(dirname "$KEY_LOCAL")"
  install -m 600 "$KEY_DOWNLOAD" "$KEY_LOCAL"
  write_env TODOAPP_KEY_FILE "$KEY_LOCAL"
  if confirm "Delete the original download at $KEY_DOWNLOAD?"; then rm -f "$KEY_DOWNLOAD"; say "deleted"; fi
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Copy the key to the Pi"
say "It goes in ~/$KEY_DIR_REMOTE on the Pi, outside the git checkout, mode 600."
while true; do
  ask PI_HOST "What you type after 'ssh' (e.g. hturner@inkpi.local):"
  PI_HOST="${PI_HOST#ssh }"; PI_HOST="${PI_HOST//[[:space:]]/}"
  # One shared connection, so the password is asked for once, not for every command.
  SSH_SOCK_DIR=$(mktemp -d)
  SSH_OPTS=(-o ControlMaster=auto -o ControlPath="$SSH_SOCK_DIR/%C" -o ControlPersist=10m)
  say "Connecting as: ssh $PI_HOST   (password prompt is from the Pi; typing is hidden)"
  ssh "${SSH_OPTS[@]}" "$PI_HOST" true && break
  warn "couldn't connect to '$PI_HOST'; check it and try again"
done
while true; do
  ask PI_REPO "TodoDisplay checkout on the Pi, under its home (e.g. Documents/TodoDisplay):"
  PI_REPO="${PI_REPO#\~/}"; PI_REPO="${PI_REPO#/home/*/}"; PI_REPO="${PI_REPO%/}"
  ssh "${SSH_OPTS[@]}" "$PI_HOST" "test -d \"\$HOME\"/$(printf %q "$PI_REPO")/src/taskFetcher" 2>/dev/null && break
  warn "no src/taskFetcher folder at ~/$PI_REPO on the Pi; check the path and try again"
done
note "ssh may ask for the Pi's password."
ssh "${SSH_OPTS[@]}" "$PI_HOST" "umask 077 && mkdir -p ~/$KEY_DIR_REMOTE"
scp -q "${SSH_OPTS[@]}" "$KEY_LOCAL" "$PI_HOST:$KEY_DIR_REMOTE/$KEY_NAME"
ssh "${SSH_OPTS[@]}" "$PI_HOST" "chmod 600 ~/$KEY_DIR_REMOTE/$KEY_NAME"
say "✓ copied to $PI_HOST:~/$KEY_DIR_REMOTE/$KEY_NAME (mode 600)"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Point the Pi's .env at it"
PI_HOME=$(ssh "${SSH_OPTS[@]}" "$PI_HOST" 'printf %s "$HOME"')
pi_env TODOAPP_PROJECT_ID "$TODOAPP_PROJECT_ID"
pi_env TODOAPP_SPACE_ID "$TODOAPP_SPACE_ID"
pi_env TODOAPP_KEY_FILE "$PI_HOME/$KEY_DIR_REMOTE/$KEY_NAME"
ssh "${SSH_OPTS[@]}" "$PI_HOST" "chmod 600 ~/$PI_REPO/src/taskFetcher/.env"
say "✓ Pi .env is mode 600"
note "Nothing reads these yet: the fetcher (#36) does. No service restart needed."

finish
